    25	
    26	/** The HTTP API the inn's website and front desk call. */
    27	public final class HttpApi {
    28	
    29	    private final Javalin server;
    30	    private final Rooms rooms;
    31	    private final ReservationService reservations;
    32	    private final SentMessages sentMessages;
    33	    private final OccupancyReport occupancyReport;
    34	    private final RevenueReport revenueReport;
    35	
    36	    public HttpApi(
    37	            Rooms rooms,
    38	            ReservationService reservations,
    39	            SentMessages sentMessages,
    40	            OccupancyReport occupancyReport,
    41	            RevenueReport revenueReport) {
    42	        this.rooms = rooms;
    43	        this.reservations = reservations;
    44	        this.sentMessages = sentMessages;
    45	        this.occupancyReport = occupancyReport;
    46	        this.revenueReport = revenueReport;
    47	
    48	        ObjectMapper jsonMapper = JsonMapper.builder()
    49	                .addModule(new JavaTimeModule())
    50	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    51	                .build();
    52	        this.server = Javalin.create(config -> {
    53	            config.showJavalinBanner = false;
    54	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
    55	        });
    56	        registerRoutes();
    57	        registerErrorHandling();
    58	    }
    59	
    60	    public Javalin server() {
    61	        return server;
    62	    }
    63	
    64	    private void registerRoutes() {
    65	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
    66	
    67	        server.post("/reservations", ctx -> {
    68	            NewReservation request = readNewReservation(ctx);
    69	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
    70	        });
    71	        server.get("/reservations/{id}", ctx ->
    72	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
    73	        server.post("/reservations/{id}/confirmation", ctx ->
    74	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
    75	        server.post("/reservations/{id}/cancellation", ctx ->
    76	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
    77	        server.post("/reservations/{id}/check-in", ctx ->
    78	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
    79	        server.post("/reservations/{id}/check-out", ctx ->
    80	                ctx.json(reservations.checkOut(reservationId(ctx))));
    81	        server.get("/reservations/{id}/document", ctx ->
    82	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
    83	
    84	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
    85	
    86	        server.get("/reports/occupancy", ctx -> {
    87	            LocalDate night = readDate(ctx);
    88	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
    89	        });
    90	        server.get("/reports/revenue", ctx -> {
    91	            YearMonth month = readMonth(ctx);
    92	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
    93	        });
    94	    }
    95	
    96	    private void registerErrorHandling() {
    97	        server.exception(HotelException.class, (exception, ctx) -> {
    98	            ctx.status(httpStatus(exception.errorCode()));
    99	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
   100	        });
   101	    }
   102	
   103	    private static int httpStatus(ErrorCode errorCode) {
   104	        return switch (errorCode) {
   105	            case INVALID_REQUEST -> 400;
   106	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
   107	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
   108	            case CAPACITY_EXCEEDED -> 422;
   109	        };
   110	    }
   111	
   112	    private static NewReservation readNewReservation(Context ctx) {
   113	        CreateReservationRequest body;
   114	        try {
   115	            body = ctx.bodyAsClass(CreateReservationRequest.class);
   116	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
   117	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
   118	        }
   119	        if (body == null
   120	                || body.roomNumber() == null
   121	                || isBlank(body.guestName())
   122	                || isBlank(body.guestEmail())
   123	                || body.checkIn() == null
   124	                || body.checkOut() == null
   125	                || body.guests() == null
   126	                || body.ratePlan() == null) {
   127	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
   128	        }
   129	
   130	        Guest guest = buildGuest(body);
   131	        return new NewReservation(
   132	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
   133	    }
   134	
   135	    private static Guest buildGuest(CreateReservationRequest body) {
   136	        boolean hasCpf = !isBlank(body.guestCpf());
   137	        boolean hasCompany = !isBlank(body.companyCnpj()) && !isBlank(body.companyName());
   138	        boolean hasPassport = !isBlank(body.guestPassport()) && !isBlank(body.guestCountry());
   139	
   140	        int identificationCount = (hasCpf ? 1 : 0) + (hasCompany ? 1 : 0) + (hasPassport ? 1 : 0);
   141	
   142	        if (identificationCount != 1) {
   143	            throw new HotelException(ErrorCode.INVALID_REQUEST,
   144	                    "exactly one guest identification must be provided: guestCpf, or companyCnpj + companyName, "
   145	                    + "or guestPassport + guestCountry");
   146	        }
   147	
   148	        if (hasCpf) {
   149	            return new IndividualGuest(body.guestName(), body.guestEmail(), body.guestCpf());
   150	        }
   151	        if (hasCompany) {
   152	            return new CorporateGuest(body.guestName(), body.guestEmail(), body.companyCnpj(), body.companyName());
   153	        }
   154	        return new ForeignGuest(body.guestName(), body.guestEmail(), body.guestPassport(), body.guestCountry());
   155	    }
   156	
   157	    private static long reservationId(Context ctx) {
   158	        String id = ctx.pathParam("id");
   159	        try {
   160	            return Long.parseLong(id);
   161	        } catch (NumberFormatException notANumber) {
   162	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
   163	        }
   164	    }
   165	
   166	    private static LocalDate readDate(Context ctx) {
   167	        String date = requiredQueryParam(ctx, "date");
   168	        try {
   169	            return LocalDate.parse(date);
   170	        } catch (DateTimeParseException badDate) {
   171	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
   172	        }
   173	    }
   174	
   175	    private static YearMonth readMonth(Context ctx) {
   176	        String month = requiredQueryParam(ctx, "month");
   177	        try {
   178	            return YearMonth.parse(month);
   179	        } catch (DateTimeParseException badMonth) {
   180	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
   181	        }
   182	    }
   183	
   184	    private static String requiredQueryParam(Context ctx, String name) {
   185	        String value = ctx.queryParam(name);
   186	        if (value == null) {
   187	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
   188	        }
   189	        return value;
   190	    }
   191	
   192	    private static boolean isBlank(String text) {
   193	        return text == null || text.isBlank();
   194	    }
   195	}
