     9	/**
    10	 * The document a guest receives when the reservation is confirmed, at check-out, and on request.
    11	 * The format varies by guest type: individuals get a receipt, companies get an invoice, foreigners get
    12	 * a booking receipt in English.
    13	 */
    14	public sealed interface ReservationDocument permits IndividualReceipt, CorporateInvoice, ForeignReceipt {
    15	
    16	    /** The formatted text of the document, ready to be sent or displayed. */
    17	    @JsonProperty("text")
    18	    String text();
    19	
    20	    /** Shared document data for JSON responses. */
    21	    long reservationId();
    22	    String guestName();
    23	    String guestCpf();
    24	    String companyCnpj();
    25	    String companyName();
    26	    String guestPassport();
    27	    String guestCountry();
    28	    int roomNumber();
    29	    LocalDate checkIn();
    30	    LocalDate checkOut();
    31	    int nights();
    32	    BigDecimal subtotal();
    33	    BigDecimal discount();
    34	    BigDecimal total();
    35	
    36	    /** Creates the appropriate document type for the guest. */
    37	    static ReservationDocument from(Reservation reservation, Room room) {
    38	        Guest guest = reservation.guest();
    39	        return switch (guest) {
    40	            case IndividualGuest individual -> new IndividualReceipt(reservation, room, individual);
    41	            case CorporateGuest corporate -> new CorporateInvoice(reservation, room, corporate);
    42	            case ForeignGuest foreign -> new ForeignReceipt(reservation, room, foreign);
    43	        };
    44	    }
    45	}
