    10	import java.util.ArrayList;
    11	import java.util.List;
    12	import java.util.Optional;
    13	import javax.sql.DataSource;
    14	
    15	/** Keeps the reservations in the database. */
    16	public final class ReservationStore {
    17	
    18	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, "
    19	            + "company_cnpj, company_name, guest_passport, guest_country, check_in, check_out, "
    20	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
    21	    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
    22	    private static final String EXCLUSION_VIOLATION = "23P01";
    23	
    24	    private final DataSource dataSource;
    25	
    26	    public ReservationStore(DataSource dataSource) {
    27	        this.dataSource = dataSource;
    28	    }
    29	
    30	    /** Saves a new reservation; the database numbers it. */
    31	    Reservation add(NewReservation request, Price price) {
    32	        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, "
    33	                + "company_cnpj, company_name, guest_passport, guest_country, check_in, check_out, guests, "
    34	                + "rate_plan, nights, subtotal, discount, total, status, amount_paid) "
    35	                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
    36	        try (Connection connection = dataSource.getConnection();
    37	                PreparedStatement statement = connection.prepareStatement(insert)) {
    38	            Guest guest = request.guest();
    39	            statement.setInt(1, request.roomNumber());
    40	            statement.setString(2, guest.name());
    41	            statement.setString(3, guest.email());
    42	            // Set identification fields based on guest type
    43	            if (guest instanceof IndividualGuest individual) {
    44	                statement.setString(4, individual.cpf());
    45	                statement.setString(5, null);
    46	                statement.setString(6, null);
    47	                statement.setString(7, null);
    48	                statement.setString(8, null);
    49	            } else if (guest instanceof CorporateGuest corporate) {
    50	                statement.setString(4, null);
    51	                statement.setString(5, corporate.cnpj());
    52	                statement.setString(6, corporate.companyName());
    53	                statement.setString(7, null);
    54	                statement.setString(8, null);
    55	            } else if (guest instanceof ForeignGuest foreign) {
    56	                statement.setString(4, null);
    57	                statement.setString(5, null);
    58	                statement.setString(6, null);
    59	                statement.setString(7, foreign.passport());
    60	                statement.setString(8, foreign.country());
    61	            }
    62	            statement.setDate(9, Date.valueOf(request.checkIn()));
    63	            statement.setDate(10, Date.valueOf(request.checkOut()));
    64	            statement.setInt(11, request.guests());
    65	            statement.setString(12, request.ratePlan().name());
    66	            statement.setInt(13, price.nights());
    67	            statement.setBigDecimal(14, price.subtotal());
    68	            statement.setBigDecimal(15, price.discount());
    69	            statement.setBigDecimal(16, price.total());
    70	            statement.setString(17, ReservationStatus.PENDING.name());
    71	            statement.setBigDecimal(18, PriceCalculator.cents(BigDecimal.ZERO));
    72	            try (ResultSet generated = statement.executeQuery()) {
    73	                generated.next();
    74	                return new Reservation(generated.getLong("id"), request, price);
    75	            }
    76	        } catch (SQLException failure) {
    77	            if (EXCLUSION_VIOLATION.equals(failure.getSQLState())) {
    78	                throw new HotelException(ErrorCode.ROOM_UNAVAILABLE,
    79	                        "room " + request.roomNumber() + " is taken on some of those nights");
    80	            }
    81	            throw new IllegalStateException("could not save the reservation", failure);
    82	        }
    83	    }
    84	
    85	    /** Saves what changes in a reservation's life: the status, what was paid and what went back. */
    86	    void update(Reservation reservation) {
    87	        try (Connection connection = dataSource.getConnection();
    88	                PreparedStatement statement = connection.prepareStatement(
    89	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    90	            statement.setString(1, reservation.status().name());
    91	            statement.setBigDecimal(2, reservation.amountPaid());
    92	            statement.setBigDecimal(3, reservation.refund());
    93	            statement.setLong(4, reservation.id());
    94	            statement.executeUpdate();
    95	        } catch (SQLException failure) {
    96	            throw new IllegalStateException("could not save reservation " + reservation.id(), failure);
    97	        }
    98	    }
    99	
   100	    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
   101	    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
   102	        try (Connection connection = dataSource.getConnection();
   103	                PreparedStatement select = connection.prepareStatement(
   104	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
   105	                                + "AND check_in < ? AND ? < check_out")) {
   106	            select.setInt(1, roomNumber);
   107	            select.setDate(2, Date.valueOf(checkOut));
   108	            select.setDate(3, Date.valueOf(checkIn));
   109	            try (ResultSet rows = select.executeQuery()) {
   110	                return rows.next();
   111	            }
   112	        } catch (SQLException failure) {
   113	            throw new IllegalStateException("could not check room " + roomNumber, failure);
   114	        }
   115	    }
   116	
   117	    public Optional<Reservation> find(long id) {
   118	        try (Connection connection = dataSource.getConnection();
   119	                PreparedStatement select = connection.prepareStatement(
   120	                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
   121	            select.setLong(1, id);
   122	            try (ResultSet rows = select.executeQuery()) {
   123	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
   124	            }
   125	        } catch (SQLException failure) {
   126	            throw new IllegalStateException("could not read reservation " + id, failure);
   127	        }
   128	    }
   129	
   130	    public List<Reservation> all() {
   131	        try (Connection connection = dataSource.getConnection();
   132	                PreparedStatement select = connection.prepareStatement(
   133	                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
   134	                ResultSet rows = select.executeQuery()) {
   135	            List<Reservation> reservations = new ArrayList<>();
   136	            while (rows.next()) {
   137	                reservations.add(read(rows));
   138	            }
   139	            return reservations;
   140	        } catch (SQLException failure) {
   141	            throw new IllegalStateException("could not read the reservations", failure);
   142	        }
   143	    }
   144	
   145	    private static Reservation read(ResultSet row) throws SQLException {
   146	        String name = row.getString("guest_name");
   147	        String email = row.getString("guest_email");
   148	        String cpf = row.getString("guest_cpf");
   149	        String cnpj = row.getString("company_cnpj");
   150	        String companyName = row.getString("company_name");
   151	        String passport = row.getString("guest_passport");
   152	        String country = row.getString("guest_country");
   153	
   154	        Guest guest;
   155	        if (cpf != null) {
   156	            guest = new IndividualGuest(name, email, cpf);
   157	        } else if (cnpj != null) {
   158	            guest = new CorporateGuest(name, email, cnpj, companyName);
   159	        } else {
   160	            guest = new ForeignGuest(name, email, passport, country);
   161	        }
   162	
   163	        NewReservation request = new NewReservation(
   164	                row.getInt("room_number"),
   165	                guest,
   166	                row.getDate("check_in").toLocalDate(),
   167	                row.getDate("check_out").toLocalDate(),
   168	                row.getInt("guests"),
   169	                RatePlan.valueOf(row.getString("rate_plan")));
   170	        Price price = new Price(
   171	                row.getInt("nights"), row.getBigDecimal("subtotal"), row.getBigDecimal("discount"),
   172	                row.getBigDecimal("total"));
   173	        return new Reservation(
   174	                row.getLong("id"),
   175	                request,
   176	                price,
   177	                ReservationStatus.valueOf(row.getString("status")),
   178	                row.getBigDecimal("amount_paid"),
   179	                row.getBigDecimal("refund"));
   180	    }
   181	}
