     1	-- The inn's rooms. They rarely change, so they come with the schema.
     2	CREATE TABLE rooms (
     3	    number       integer PRIMARY KEY,
     4	    type         text NOT NULL,
     5	    capacity     integer NOT NULL CHECK (capacity > 0),
     6	    nightly_rate numeric(10, 2) NOT NULL CHECK (nightly_rate > 0)
     7	);
     8	
     9	INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
    10	    (101, 'STANDARD', 2, 249.90),
    11	    (102, 'STANDARD', 2, 249.90),
    12	    (201, 'DELUXE', 3, 389.90),
    13	    (202, 'DELUXE', 3, 389.90),
    14	    (301, 'SUITE', 4, 579.90);
    15	
    16	-- btree_gist lets one constraint compare the room number (equality) and the nights (overlap) together.
    17	CREATE EXTENSION IF NOT EXISTS btree_gist;
    18	
    19	CREATE TABLE reservations (
    20	    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    21	    room_number integer NOT NULL REFERENCES rooms (number),
    22	    guest_name  text NOT NULL,
    23	    guest_email text NOT NULL,
    24	    guest_cpf   text NOT NULL,
    25	    check_in    date NOT NULL,
    26	    check_out   date NOT NULL,
    27	    guests      integer NOT NULL CHECK (guests >= 1),
    28	    rate_plan   text NOT NULL,
    29	    nights      integer NOT NULL,
    30	    subtotal    numeric(10, 2) NOT NULL,
    31	    discount    numeric(10, 2) NOT NULL,
    32	    total       numeric(10, 2) NOT NULL,
    33	    status      text NOT NULL,
    34	    amount_paid numeric(10, 2) NOT NULL,
    35	    refund      numeric(10, 2),
    36	    CHECK (check_out > check_in),
    37	    -- a room is never booked twice for the same night, even when two requests arrive at the same time
    38	    CONSTRAINT reservations_no_double_booking
    39	        EXCLUDE USING gist (room_number WITH =, daterange(check_in, check_out) WITH &&)
    40	        WHERE (status <> 'CANCELLED')
    41	);
    42	
    43	-- every message the inn sent, so the front desk can check what each guest received
    44	CREATE TABLE messages (
    45	    id        bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
